examples.template:
MonarchNotificationsBell(onClick = { showNotifications = true }, unreadCount = {{unreadCount}}) {
    MonarchIcon(SampleIcons.Bell, contentDescription = null)
}
if (showNotifications) {
    MonarchBottomSheet(onDismissRequest = { showNotifications = false }) {
        MonarchNotificationCenter(
            items = items,
            modifier = Modifier.fillMaxWidth().heightIn(max = 400.dp),
            now = {{now|millis}},
            onMarkRead = { read = read + it },
            onMarkAllRead = { read = items.map { it.id }.toSet() },
            footer = { MonarchLink(text = {{seeAll}}, onClick = {}, variant = MonarchLinkVariant.Standalone) },
        )
    }
}

